src = open('ar_source_part1.md', encoding='utf-8').read()
head, *blocks = re.split(r'(?m)^(?=الصنف \d+ \(#\d+\))', src)
out = ['# Batch 30, part 1: Arabic copy for 876-891 with the before/after table APPROVED by Dr. Wassim Habib (2026-11-08).\n'
       '# Generated by apply_part1.py from ar_source_part1.md; 886 has no GI number (decision (b), same rule as 885).\n'
       '# Do not build pages yet: all 25 are built together once the remaining 15 arrive.\n\n']
n = 0
for b in blocks:
    fid = int(re.search(r'\(#(\d+)\)', b).group(1))
    for old, new in R[fid]:
        assert b.count(old) == 1, (fid, old[:70], b.count(old))
        b = b.replace(old, new)
        n += 1
    left = [l for l in b.split('\n') if 'بودي' in l.replace(CTA, '')]
    assert not left, (fid, left)                      # every Boodi mention is the approved CTA
    out.append(b)
open('ar_corrected_part1.md', 'w', encoding='utf-8', newline='\n').write(''.join(out))
print('foods', len(blocks), '| replacements', n)
